//! TinySegmenter model weights, machine-derived from the reference.
//!
//! DO NOT EDIT BY HAND: these are mechanically extracted model weights,
//! checked in as data rather than transcribed by hand.

use super::{Ctype, WordTable};

/// The model's constant offset (`this.BIAS__`).
pub(crate) const BIAS: i32 = -332;

/// Character type of one UTF-16 code unit — the reference `ctype_`.
///
/// Order is significant: The reference tests its patterns in sequence and
/// returns the first that matches, so the numeral set (`M`) wins over the
/// general Han range (`H`) for characters such as 一 and 十.
pub(crate) const fn ctype(u: u16) -> Ctype {
    match u {
        0x30..=0x39 => Ctype::N,
        0x41..=0x5a | 0x61..=0x7a => Ctype::A,
        0x3006
        | 0x4e01..=0x4e02
        | 0x4e04..=0x4e06
        | 0x4e08
        | 0x4e0a..=0x4e5c
        | 0x4e5e..=0x4e8b
        | 0x4e8d..=0x4e93
        | 0x4e95..=0x5103
        | 0x5105..=0x5145
        | 0x5147..=0x516a
        | 0x516c
        | 0x516e..=0x5340
        | 0x5342
        | 0x5344..=0x56da
        | 0x56dc..=0x767d
        | 0x767f..=0x9fcc => Ctype::H,
        0x3007 | 0x4e00 | 0x4e03 | 0x4e07 | 0x4e09 | 0x4e5d | 0x4e8c | 0x4e94 | 0x5104 | 0x5146
        | 0x516b | 0x516d | 0x5341 | 0x5343 | 0x56db | 0x767e => Ctype::M,
        0x3041..=0x309f => Ctype::I,
        0x30a0..=0x30ff => Ctype::K,
        _ => Ctype::O,
    }
}

/// Whether `removePuncTokens` strips this code unit from inside a token.
///
/// The reference class holds 76 punctuation characters — fullwidth and halfwidth
/// forms of the same marks, side by side — plus `\s`. Generated by testing the
/// real method against every code unit, because transcribing ＿/_ , －/-, ･/・,
/// ，/, and ｡/。 correctly by eye is a coin flip.
pub(crate) const fn is_punct(u: u16) -> bool {
    matches!(u,
        0x9..=0xd
        | 0x20..=0x26
        | 0x28..=0x2f
        | 0x3a..=0x40
        | 0x5b
        | 0x5d..=0x60
        | 0x7b..=0x7e
        | 0xa0
        | 0xab
        | 0xbb
        | 0x1680
        | 0x2000..=0x200a
        | 0x2028..=0x2029
        | 0x202f
        | 0x205f
        | 0x226a..=0x226b
        | 0x2500
        | 0x3000..=0x3002
        | 0x300c..=0x300d
        | 0x30fb
        | 0xfeff
        | 0xff01..=0xff06
        | 0xff08..=0xff0f
        | 0xff1a..=0xff20
        | 0xff3b..=0xff40
        | 0xff5b..=0xff5e
        | 0xff61..=0xff65
    )
}

